css='''*{box-sizing:border-box}html,body{margin:0;background:#080a0c;color:#F1F3F5;font-family:Finance,sans-serif}body{display:flex;align-items:center;flex-direction:column;min-height:100vh;padding:20px}button,input{font:inherit}#frame{position:relative;flex:none;overflow:hidden}#composition{position:relative;width:1080px;height:1920px;background:#101214;overflow:hidden;transform-origin:top left}.decoration{position:absolute;inset:0;pointer-events:none}.decoration:before{content:'';position:absolute;left:90px;right:90px;top:108px;border-top:2px solid #23364B}.decoration:after{content:'';position:absolute;right:90px;top:140px;height:110px;border-right:2px solid #23364B}.scene{position:absolute;inset:0;opacity:0}.content{width:100%;height:100%;padding:170px 90px 104px;display:flex;flex-direction:column;gap:46px}.kicker{font-size:38px;letter-spacing:4px;font-weight:700;color:#ADB9C8;line-height:1.4;max-width:900px}h1{font-size:100px;line-height:1.07;letter-spacing:-4px;margin:0;font-weight:700;max-width:900px}.body{display:flex;flex-direction:column;gap:36px;flex:1;min-height:0;padding-top:10px;position:relative}.mega{font-size:252px;line-height:1.05;letter-spacing:-12px;font-weight:700;color:#A9C9E8;font-variant-numeric:tabular-nums;margin-top:65px}.mega.compact{font-size:180px;letter-spacing:-9px;margin-top:15px}.label{font-size:43px;line-height:1.55;color:#ADB9C8;letter-spacing:1px;font-weight:700}.case{padding:6px 0 26px;border-bottom:2px solid #23364B}.eyebrow{font-size:42px;line-height:1.5;color:#ADB9C8;letter-spacing:1px}.figure{font-size:168px;line-height:1.2;font-weight:700;color:#A9C9E8;letter-spacing:-7px;font-variant-numeric:tabular-nums}.case .label{font-size:38px}.case .label .count{font-size:88px;color:#A9C9E8;line-height:1}.label>.count{font-size:100px;color:#A9C9E8;line-height:1}.stack{font-size:56px;font-weight:700;line-height:1.5}.rule{width:100%;height:2px;background:#23364B;flex:none;margin:14px 0}.fund{font-size:66px;line-height:1.25;font-weight:700;color:#A9C9E8}.step{font-size:42px;color:#ADB9C8;border-bottom:2px solid #23364B;padding:32px 0;line-height:1.4}.step span{font-size:60px;color:#F1F3F5;display:block;margin-top:14px;font-weight:700}.brands{font-size:68px;font-weight:700;line-height:1.7;color:#A9C9E8}.statement{font-size:86px;font-weight:700;line-height:1.1;letter-spacing:-2px}.accent{color:#A9C9E8}.lesson{font-size:54px;line-height:1.35;font-weight:700;border-bottom:2px solid #23364B;padding-bottom:28px}.lesson span{font-size:36px;color:#ADB9C8;display:block;margin-bottom:10px}.cta{font-size:76px;line-height:1.2;font-weight:700;color:#A9C9E8;margin-top:90px}.web{font-size:46px;line-height:1.5;color:#ADB9C8;margin-top:60px}.source{font-size:44px;line-height:1.5;color:#ADB9C8;margin-top:auto;min-height:132px;padding-top:10px;max-width:900px}.car{width:900px;height:260px;flex:none;color:#6F91B0;opacity:0;margin-top:22px}.reveal{opacity:0}.count{font-variant-numeric:tabular-nums}#captions{position:absolute;left:90px;right:90px;bottom:290px;font-size:76px;line-height:1.2;letter-spacing:-1.3px;color:#F1F3F5;min-height:190px;max-height:290px;display:flex;align-items:end;pointer-events:none}#captions span{background:#101214;padding:8px 0;box-decoration-break:clone;-webkit-box-decoration-break:clone}#progress{position:absolute;left:90px;right:90px;top:108px;height:2px;background:#A9C9E8;transform-origin:left;transform:scaleX(0)}#controls{width:min(600px,100%);margin:16px auto;display:flex;gap:10px;align-items:center;flex-wrap:wrap;font-size:14px;color:#c6d0db}button{border:1px solid #344454;background:#18222d;color:#f1f3f5;border-radius:5px;padding:9px 13px;cursor:pointer}button:focus-visible,input:focus-visible{outline:2px solid #A9C9E8}#seek{flex:1;min-width:130px;accent-color:#A9C9E8}#status{width:100%;font-size:12px;line-height:1.5;min-height:18px}details{max-width:600px;width:100%;font-size:13px;line-height:1.6;color:#adb9c8}details a{color:#A9C9E8}#notes{padding-bottom:30px}#scene-8 .body{gap:25px}#scene-9 h1{font-size:125px}#scene-5 .body{padding-top:45px}@media(prefers-reduced-motion:reduce){button{scroll-behavior:auto}}'''
js='''const SPEC=__SPEC__;const CAPTIONS=__CAPTIONS__;
const FPS=30,DURATION=SPEC.duration,T=60/122;const beatT=n=>Math.round(n*T*FPS)/FPS;
window.__timelines=window.__timelines||{};
const tl=gsap.timeline({paused:true});
const counters=[];const anchors=[];
SPEC.beats.slice(0,-1).forEach((beat,i)=>{
 const s=document.getElementById('scene-'+i),start=beatT(beat),next=beatT(SPEC.beats[i+1]);
 tl.fromTo(s,{opacity:0},{opacity:1,duration:.26,ease:'power1.out',immediateRender:false},start);
 if(i<9)tl.to(s,{opacity:0,duration:.26,ease:'power1.in'},next);
 s.querySelectorAll('.reveal').forEach(el=>{
  const offset=Number(el.dataset.offset),at=beatT(beat+offset);
  anchors.push({scene:i+1,beat:beat+offset,time:at,frame:Math.round(at*FPS)});
  tl.fromTo(el,{opacity:0,y:18},{opacity:1,y:0,duration:.52,ease:'power2.out',immediateRender:false},at);
 });
 s.querySelectorAll('.count').forEach(el=>{
  const parent=el.closest('.reveal');const at=beatT(beat+Number(parent?.dataset.offset||0));
  counters.push({el,start:at,end:at+4*T,value:Number(el.dataset.value),from:Number(el.dataset.from||0),prefix:el.dataset.prefix||'',suffix:el.dataset.suffix||''});
 });
 const car=s.querySelector('.car');if(car){
  tl.fromTo(car,{opacity:0,x:-38},{opacity:.65,x:0,duration:4*T,ease:'power2.out',immediateRender:false},beatT(beat+8));
  tl.to(car,{x:32,duration:12*T,ease:'sine.inOut'},beatT(beat+12));
  if(i===6)tl.to(car,{opacity:0,duration:4*T,ease:'power1.in'},beatT(beat+20));
 }
});
tl.from('#captions',{opacity:0,duration:.25},0);
tl.fromTo('#progress',{scaleX:0},{scaleX:1,duration:DURATION,ease:'none'},0);
const cap=document.querySelector('#captions span');
function updateText(time){
 counters.forEach(c=>{const p=Math.max(0,Math.min(1,(time-c.start)/(c.end-c.start))),e=1-Math.pow(1-p,3),v=c.from+(c.value-c.from)*e;const str=Number.isInteger(c.value)?(c.from>=1900?String(Math.round(v)):Math.round(v).toLocaleString('en-US')):v.toFixed(1);c.el.textContent=c.prefix+str+c.suffix;});
 const line=CAPTIONS.find(x=>time>=x.start&&time<x.end);cap.textContent=line?line.text:'';
}
tl.eventCallback('onUpdate',()=>updateText(tl.time()));
window.__timelines['uniland-ev-finance']=tl;
window.FILM={spec:SPEC,anchors,captions:CAPTIONS,seek:time=>{const t=Math.max(0,Math.min(DURATION,Math.round(time*FPS)/FPS));tl.time(t);updateText(t);}};
const voice=document.getElementById('voice'),music=document.getElementById('music');
let playing=false,raf=0;music.volume=.75;voice.volume=1;
const seek=document.getElementById('seek'),clock=document.getElementById('clock'),play=document.getElementById('play'),status=document.getElementById('status');
function fmt(t){return Math.floor(t/60)+':'+String(Math.floor(t%60)).padStart(2,'0');}
function ui(t){seek.value=t;clock.textContent=fmt(t)+' / '+fmt(DURATION);}
function tick(){if(!playing)return;const t=Math.min(voice.currentTime,DURATION);if(Math.abs(music.currentTime-t)>.05)music.currentTime=t;window.FILM.seek(t);ui(t);if(t>=DURATION-.025||voice.ended){stop();window.FILM.seek(DURATION);ui(DURATION);return;}raf=requestAnimationFrame(tick);}
function stop(){playing=false;voice.pause();music.pause();cancelAnimationFrame(raf);play.textContent='Play';}
async function start(){if(playing){stop();return;}if(voice.currentTime>=DURATION-.1){voice.currentTime=0;music.currentTime=0;}try{music.currentTime=voice.currentTime;await Promise.all([voice.play(),music.play()]);playing=true;play.textContent='Pause';status.textContent='English narration · 122 BPM · Offline playback';tick();}catch(e){stop();status.textContent='Playback could not start. Press Play again. '+e.message;}}
play.addEventListener('click',start);
seek.addEventListener('input',()=>{const t=Number(seek.value);voice.currentTime=t;music.currentTime=t;window.FILM.seek(t);ui(t);});
document.getElementById('replay').addEventListener('click',()=>{stop();voice.currentTime=0;music.currentTime=0;window.FILM.seek(0);ui(0);start();});
document.getElementById('mute').addEventListener('click',e=>{voice.muted=!voice.muted;music.muted=voice.muted;e.target.textContent=voice.muted?'Unmute':'Mute';e.target.setAttribute('aria-pressed',String(voice.muted));});
document.getElementById('bgm').addEventListener('click',e=>{music.volume=music.volume?0:.75;e.target.textContent=music.volume?'BGM on':'BGM off';e.target.setAttribute('aria-pressed',String(Boolean(music.volume)));});
window.addEventListener('keydown',e=>{if(e.code==='Space'&&!['INPUT','BUTTON','SUMMARY'].includes(document.activeElement.tagName)){e.preventDefault();start();}});
function resize(){const k=Math.min((innerWidth-40)/1080,(innerHeight-190)/1920,1);const s=Math.max(.08,k);document.getElementById('composition').style.transform='scale('+s+')';document.getElementById('frame').style.width=(1080*s)+'px';document.getElementById('frame').style.height=(1920*s)+'px';}
window.addEventListener('resize',resize);resize();ui(0);window.FILM.seek(0);
if(window.top!==window.self){document.body.style.padding='0';document.getElementById('controls').hidden=true;document.getElementById('notes').hidden=true;document.getElementById('composition').style.transform='none';document.getElementById('frame').style.width='1080px';document.getElementById('frame').style.height='1920px';}
'''.replace('__SPEC__',json.dumps(dict(beats=BEATS,bpm=122,fps=30,width=1080,height=1920,duration=duration))).replace('__CAPTIONS__',json.dumps(captions))
notes='<p>Sources supplied by the user. Original pages were not independently verified because network access returned proxy 403. Reported figures retain attribution. Selected brands are illustrative, not an exhaustive market list. Profitability and RMB1.6bn claims are excluded. Captions are phrase-timed estimates within measured TTS sentences, not forced-aligned word timestamps.</p><ol>'+''.join(f'<li><a href="{html.escape(u)}" target="_blank" rel="noopener noreferrer">{html.escape(label)}</a></li>' for label,u in SOURCES)+'</ol><p>Audio: Kokoro am_michael synthetic English male narration; original deterministic 122 BPM percussion and low pad. No stock footage, photos or 3D models. Two inline SVG vehicle silhouettes.</p>'
result=f'''<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>UNILAND · China EV Market Brief</title><style>@font-face{{font-family:Finance;src:url(data:font/ttf;base64,{font('brand-regular.ttf')}) format('truetype');font-weight:400;font-display:block}}@font-face{{font-family:Finance;src:url(data:font/ttf;base64,{font('brand-bold.ttf')}) format('truetype');font-weight:700;font-display:block}}{css}</style></head><body><div id="frame" data-composition-id="uniland-ev-finance" data-start="0" data-duration="{duration}" data-width="1080" data-height="1920"><main id="composition"><div class="decoration" data-layout-ignore></div>{''.join(parts)}<div id="captions" aria-live="off"><span></span></div><div id="progress" data-layout-ignore></div><audio id="voice" data-start="0" data-duration="{duration}" data-track-index="4" data-volume="1" preload="auto" src="data:audio/mpeg;base64,{audio('voice.mp3')}"></audio><audio id="music" data-start="0" data-duration="{duration}" data-track-index="5" data-volume="0.75" preload="auto" src="data:audio/mpeg;base64,{audio('bgm.mp3')}"></audio></main></div><div id="controls"><button id="play" type="button">Play</button><button id="replay" type="button">Replay</button><input id="seek" type="range" min="0" max="{duration}" value="0" step="0.0333333333" aria-label="Playback position"><span id="clock"></span><button id="mute" type="button" aria-pressed="false">Mute</button><button id="bgm" type="button" aria-pressed="true">BGM on</button><div id="status">Click Play to start · English male narration · 122 BPM · No internet required</div></div><details id="notes"><summary>Sources & production notes</summary>{notes}</details><script>{gsap}</script><script>{js}</script></body></html>'''
(p/'index.html').write_text(result)
(p/'storyboard.json').write_text(json.dumps([dict(scene=i+1,start=BEATS[i]*T,end=BEATS[i+1]*T,voice=' '.join(SCRIPTS[i]),headline=re.sub('<[^>]+>',' ',s['title']),source=s['source']) for i,s in enumerate(scenes)],indent=2,ensure_ascii=False))
print('Built',len(result.encode()),'bytes',duration,'seconds')
